+/* Spatial-hash broadphase (cell = brick width) */
+function candidatePairs(){
+  const cell=0.55, map=new Map(), pairs=[], all=state.bricks;
+  const key=(cx,cy)=>cx*100000+cy;
+  for(const b of all){
+    const r=0.45; // approx half-diagonal bound for a brick
+    const x0=Math.floor((b.x-r)/cell), x1=Math.floor((b.x+r)/cell);
+    const y0=Math.floor((b.y-r)/cell), y1=Math.floor((b.y+r)/cell);
+    for(let cx=x0;cx<=x1;cx++)for(let cy=y0;cy<=y1;cy++){
